{
  "findings": [
    {
      "check_id": "CKV_AZURE_114",
      "title": "Ensure that key vault secrets have 'content_type' set",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The key vault secret 'database_connection_string' is missing the 'content_type' attribute, which can lead to difficulties in managing and understanding the secret's purpose."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_secret\" \"database_connection_string\" {\n  name         = \"database-connection-string\"\n  value        = \"Server=tcp:${azurerm_mssql_server.legal_sql_server.fully_qualified_domain_name},1433;Database=${azurerm_mssql_database.legal_metadata_db.name};User ID=${var.sql_admin_username};Password=${var.sql_admin_password};Encrypt=true;TrustServerCertificate=false;Connection Timeout=30;\"\n  key_vault_id = azurerm_key_vault.legal_keyvault.id\n  content_type = \"SQL Connection String\"\n  depends_on = [azurerm_mssql_database.legal_metadata_db]\n}",
  "fix_summary": "Added 'content_type' attribute to the 'database_connection_string' secret to improve manageability and clarity."
}
